--
-- Structure for view `statutory_process_matrix`
--
DROP TABLE IF EXISTS `statutory_process_matrix`;

DROP VIEW IF EXISTS `statutory_process_matrix`;
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `statutory_process_matrix`  AS SELECT `t`.`sort_order` AS `type_order`, `t`.`name` AS `procurement_type`, `t`.`code` AS `procurement_type_code`, `m`.`sort_order` AS `method_order`, `m`.`name` AS `method`, `m`.`code` AS `method_code`, `s`.`stage_order` AS `stage_order`, `s`.`code` AS `stage_code`, `s`.`name` AS `stage`, (case `s`.`code` when 'BID_DRAFT' then 'bid draft and approval' when 'BID_ISSUANCE' then 'Issuance of the Bid' when 'BIDDING' then 'Bidding period' when 'EVALUATION' then 'Evaluation period (from date of opening)' when 'CC_DECISION' then 'Contracts committee decision period' when 'BEB_DISPLAY' then 'BEB Display' when 'DRAFT_CONTRACT' then 'Submission of draft contract (From display of BEB)' end) AS `worksheet_column`, (case when (`p`.`id` is null) then 'NOT_IN_PROCESS' else `p`.`period_mode` end) AS `period_mode`, (case `p`.`period_mode` when 'NO_MINIMUM' then NULL when 'NOT_APPLICABLE' then NULL else `p`.`days` end) AS `days`, `v`.`variant_count` AS `variant_count`, `v`.`variant_text` AS `variant_text`, `s`.`date_role` AS `date_role`, `s`.`anchors_from_code` AS `anchors_from_code`, ((case when (`v`.`variant_text` is not null) then `v`.`variant_text` when (`p`.`period_mode` = 'NO_MINIMUM') then 'No minimum' when (`p`.`period_mode` = 'NOT_APPLICABLE') then 'NA' when (`p`.`period_mode` = 'MANDATORY') then convert(cast(`p`.`days` as char charset cp850) using utf8mb4) else '' end) collate utf8mb4_general_ci) AS `worksheet_value` FROM (((((`statutory_rules` `r` join `procurement_types` `t` on((`t`.`id` = `r`.`procurement_type_id`))) join `procurement_methods` `m` on((`m`.`id` = `r`.`procurement_method_id`))) join `process_stages` `s`) left join `statutory_periods` `p` on(((`p`.`rule_id` = `r`.`id`) and (`p`.`stage_id` = `s`.`id`)))) left join (select `statutory_period_variants`.`period_id` AS `period_id`,count(0) AS `variant_count`,group_concat((case `statutory_period_variants`.`variant_kind` when 'ALTERNATIVE' then concat(`statutory_period_variants`.`days`,' (',lower(`statutory_period_variants`.`variant_name`),')') else concat(`statutory_period_variants`.`days`,' ',lower(`statutory_period_variants`.`variant_name`)) end) order by `statutory_period_variants`.`ordinal` ASC,`statutory_period_variants`.`days` ASC separator ' / ') AS `variant_text` from `statutory_period_variants` group by `statutory_period_variants`.`period_id`) `v` on((`v`.`period_id` = `p`.`id`))) ;

